nderstanding","difficulty_level":"basic","marks":1,"calculator":true,"calculator_policy":"permitted","assessment_style":"myp_summative","response_guidance":"Write one letter, P to T, in the box.","source":"myp4-grade9-statistics-version-c-2025-26"}},{"n":19,"t":"assess_parts","p":"Six mangoes have a mean mass of 240 g. A seventh mango is added, raising the mean of all seven to 250 g. [3]\n**(a)** Total mass of the six  **(b)** Mass of the seventh mango","d":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Six mangoes have a mean mass of 240 g. A seventh mango is added, raising the mean of all seven to 250 g. [3]"}]},{"type":"paragraph","content":[{"type":"text","text":"**(a)** Total mass of the six  **(b)** Mass of the seventh mango"}]}]},"e":"(a) 6 × 240 = 1 440 g. (b) 7 × 250 = 1 750 g, so the seventh mango is 1 750 − 1 440 = 310 g.","m":3,"df":"easy","tp":"Mean","st":"missing value from a mean","cfg":{"question_number":19,"paper_question_key":19,"paper_section":"A","myp_criterion":"D","criterion_label":"Criterion D — Applying mathematics in real-life contexts","criterion_title":"Applying mathematics in real-life contexts","difficulty_level":"basic","marks":3,"calculator":true,"calculator_policy":"permitted","assessment_style":"myp_summative","marking_breakdown":[{"label":"(a)","marks":1,"focus":"total of six"},{"label":"(b)","marks":2,"focus":"new total and seventh mass"}],"parts":[{"id":"a","label":"(a)","prompt":"Total mass of the six mangoes","kind":"numeric","points":1,"hints":["Re-read what (a) is asking you to find.","Use the data and method named in the question for (a)."],"unit":"g","answer":1440,"tolerance":0},{"id":"b","label":"(b)","prompt":"Mass of the seventh mango","kind":"numeric","points":2,"hints":["Re-read what (b) is asking you to find.","Use the data and method named in the question for (b)."],"unit":"g","answer":310,"tolerance":0}],"source":"myp4-grade9-statistics-version-c-2025-26"}},{"n":20,"t":"assess_parts","